head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.vBzProcsNo = "";
scwin.vListBzTpCd = "";

// 발행기관목록관련

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — listSync 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload =  async function() {
    try {

        // 초기화함수

        scwin.init();

        scwin.listSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF40005.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {

};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출).
 * @returns {void}
 * @hidden N
 */
scwin.init = function () {

    scwin.vBzProcsNo =  $c.data.getParameter("bzProcsNo");
    scwin.vListBzTpCd = "200";
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @event
 * @name scwin.grd_List_oncelldblclick
 * @desc scwin.grd_List_oncelldblclick
 * @returns {void}
 * @hidden N
 */
scwin.grd_List_oncelldblclick = async function (rowIndex, columnIndex, columnId) {
    try {

        if ("FUNC_ACPT" === columnId) {
            let vAnswer = await $c.win.confirm("승인처리 하시겠습니까?");
            if (vAnswer === true) {
                await scwin.trs("35");
            }
        } else if ("FUNC_RJCT" === columnId) {

            let vAnswer = await $c.win.confirm("불가처리 하시겠습니까?");
            if (vAnswer === true) {
                await scwin.trs("36");
            }
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF40005.grd_List_oncelldblclick" });
    }
};

/**
 * @method
 * @event
 * @name scwin.btn_Close_onclick
 * @description :닫기
 * @returns {void}
 * @hidden N
 */
scwin.btn_Close_onclick = function(e) {
    try {
    $c.win.closeAllPopup();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF40005.btn_Close_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @func
 * @name scwin.listSync
 * @description 수정요청리스트 조회
 * @returns {void}
 * @hidden N
 */
scwin.listSync = function() {

    dma_searchReq.set("bzProcsNo",scwin.vBzProcsNo);
    dma_searchReq.set("listInvstgBzTpCd",scwin.vListBzTpCd);

    const sbmOptions = {
        id : "sbm_stockoptionAdjreqList",
        method: "get",
        ref: "dma_searchReq",
        action : "/api/listing/lstmgt/stockoption-adjreq/select-list",
        target : "dltStockoptionAdjreqRes=body",
        isProcessMsg : true
    };

    const res = $c.sbm.executeDynamic(sbmOptions);
    // if (res.responseJSON.success) {

    // }

};

/**
 * @method
 * @FUnc
 * @name scwin.trs
 * @description :접수또는 반려처리
 * @returns {void}
 * @hidden N
 */
scwin.trs = async function(listProcsStatCd) {

    let rowPostion = dltStockoptionAdjreqRes.getRowPosition();
    dma_stockoptionAdjReq.set("listProcsStatCd", listProcsStatCd);
    dma_stockoptionAdjReq.set("bzProcsNo", scwin.vBzProcsNo)   ;
    dma_stockoptionAdjReq.set("listBzTpCd",  scwin.vListBzTpCd) ;
    dma_stockoptionAdjReq.set("listBzDtlTpCd", dltStockoptionAdjreqRes.getCellData(rowPostion, "listBzDtlTpCd")) ;
    dma_stockoptionAdjReq.set("adjReqProcsNo", dltStockoptionAdjreqRes.getCellData(rowPostion, "adjReqProcsNo"));

    const sbmOptions = {
            id : "sbm_rejectOrProcesss",
            action : "/api/listing/lstmgt/stockoption-adjreq/process-stkopt",
            method : "post",
            ref : "dma_stockoptionAdjReq",
            isProcessMsg : true
    };

    const res =  await $c.sbm.executeDynamic(sbmOptions);
    if (res.responseJSON.success === true) {
        await $c.win.alert("처리 성공했습니다");
        await $c.win.closePopup();
    }

};
